//! Correctness test for the on-chain Groth16/BLS12-381 verifier, against a REAL
//! proof + verifying key generated by circom/snarkjs in CI (see the zk-fixture
//! workflow). Gated behind the `zk-fixture` feature so the normal contracts job
//! (which has no generated fixture) does not compile it.
//!
//! `fixture_data.rs` is written by `scripts/zk/gen-fixture.mjs` before this runs.
#![cfg(feature = "zk-fixture")]

use policy_verifier::groth16::{Groth16Proof, Groth16Vk};
use policy_verifier::{PolicyVerifier, PolicyVerifierClient};
use soroban_sdk::testutils::Address as _;
use soroban_sdk::{vec, Address, BytesN, Env, Vec};

include!("fixture_data.rs");

fn decode_hex(s: &str) -> std::vec::Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn bn<const N: usize>(env: &Env, s: &str) -> BytesN<N> {
    let v = decode_hex(s);
    let mut arr = [0u8; N];
    arr.copy_from_slice(&v);
    BytesN::from_array(env, &arr)
}

#[test]
fn verify_groth16_accepts_valid_and_rejects_tampered() {
    let env = Env::default();
    let id = env.register(PolicyVerifier, ());
    let client = PolicyVerifierClient::new(&env, &id);

    let mut ic: Vec<BytesN<96>> = vec![&env];
    for h in IC {
        ic.push_back(bn::<96>(&env, h));
    }
    let vk = Groth16Vk {
        alpha_g1: bn::<96>(&env, ALPHA_G1),
        beta_g2: bn::<192>(&env, BETA_G2),
        gamma_g2: bn::<192>(&env, GAMMA_G2),
        delta_g2: bn::<192>(&env, DELTA_G2),
        ic,
    };
    let proof = Groth16Proof {
        a: bn::<96>(&env, PROOF_A),
        b: bn::<192>(&env, PROOF_B),
        c: bn::<96>(&env, PROOF_C),
    };
    let mut pubs: Vec<BytesN<32>> = vec![&env];
    for h in PUBLIC_INPUTS {
        pubs.push_back(bn::<32>(&env, h));
    }

    // A valid proof for the committed public inputs must verify.
    assert!(
        client.verify_groth16(&vk, &proof, &pubs),
        "valid Groth16 proof should verify on-chain"
    );

    // Flip one byte of the first public input: the proof must now be rejected.
    let mut bad = [0u8; 32];
    bad.copy_from_slice(&decode_hex(PUBLIC_INPUTS[0]));
    bad[31] ^= 0x01;
    let mut tampered: Vec<BytesN<32>> = vec![&env, BytesN::from_array(&env, &bad)];
    for h in PUBLIC_INPUTS.iter().skip(1) {
        tampered.push_back(bn::<32>(&env, h));
    }
    assert!(
        !client.verify_groth16(&vk, &proof, &tampered),
        "tampered public input should be rejected"
    );

    // Stored-VK path (pp/2 production): the admin pins the VK once, then the
    // vault verifies with only a proof. Same accept/reject behaviour.
    env.mock_all_auths();
    let admin = Address::generate(&env);
    client.init(&admin);
    client.set_groth16_vk(&admin, &vk);
    assert_eq!(
        client.get_groth16_vk_hash(),
        client.get_groth16_vk_hash(),
        "vk hash is a stable view"
    );
    assert!(
        client.verify_groth16_stored(&proof, &pubs),
        "stored-VK verify should accept the valid proof"
    );
    assert!(
        !client.verify_groth16_stored(&proof, &tampered),
        "stored-VK verify should reject a tampered input"
    );
}
